const slots = $slots;
const clock = (hhmm) => hhmm.split(":").map(Number);
const lastTicket = slots.tickets.find((ticket) => ticket.day === slots.shift.day && clock(ticket.clock) > clock(slots.shift.from));
if (lastTicket === undefined) { throw new Error("no ticket attempt matches the closing window"); }
const success = slots.tickets.find((ticket) => ticket.day === slots.shift.day && clock(ticket.clock) <= clock(slots.shift.from));
return "Friday " + lastTicket.day + ": " + lastTicket.clock + ". Monday " + success.day + ": " + success.clock + ".";

