const slots = $slots;
const minutesOf = (hhmm) => { const parts = String(hhmm).split(":"); return Number(parts[0]) * 60 + Number(parts[1]); };
const lastTicketMinutes = minutesOf(slots.lastTicket);
const breakMinutes = minutesOf(slots.break);
const succeeds = slots.askedOn.day === slots.shifts[0].day &&
  minutesOf(slots.askedOn) <= lastTicketMinutes &&
  minutesOf(slots.availableOn) >= breakMinutes;
if (succeeds) { return "Friday (" + slots.askedOn + ") succeeds."; }
return "Neither shift: " + slots.askedOn + " is inside the last ticket window, and " + slots.availableOn + " is after the break.";

