@answer jsEval
const slots = $slots;
const minutesOf = (clock) => {
  const parts = clock.split(":");
  return Number(parts[0]) * 60 + Number(parts[1]);
};
const lastTicketMinutes = minutesOf(slots.lastTicket.from) + slots.lastTicket.to;
const lastTicketSuccess = lastTicketMinutes > minutesOf(slots.person.tickets[0].clock);
const breakSuccess = minutesOf(slots.break.from) < minutesOf(slots.person.tickets[1].clock);
const openSuccess = slots.shift.to > slots.person.tickets[0].clock && slots.shift.from < slots.person.tickets[1].clock;
let success = null;
if (lastTicketSuccess && breakSuccess && openSuccess) {
  success = "The last ticket of the day succeeds on both the Friday and the Monday shifts.";
} else if (lastTicketSuccess && breakSuccess) {
  success = "The last ticket of the day succeeds on Friday, but not on Monday.";
} else if (lastTicketSuccess) {
  success = "The last ticket of the day succeeds on " + slots.person.tickets[0].day + ".";
} else if (breakSuccess) {
  success = "The break succeeds on " + slots.person.tickets[1].day + ", but the last ticket does not.";
} else {
  success = "Neither the last ticket nor the break succeeds on both shifts.";
}
return success;

