@derive jsEval
const slots = $slots;
const trueValue = { active: true, name: "true" };
const falseValue = { active: false, name: "false" };
const derived = [];
const derivedNames = new Set();
const holds = (condition) => condition.active === trueValue.active || condition.active === falseValue.active;
let changed = true;
while (changed) {
  changed = false;
  for (const rule of slots.rules) {
    if (deriveRule(rule, slots.known) === false) {
      continue;
    }
    const name = rule.consequent.name;
    if (derivedNames.has(name)) {
      continue;
    }
    derivedNames.add(name);
    derived.push(rule.consequent);
    changed = true;
  }
}
probe(derived.length > 0, "the stated rules must produce at least one derived value");
const compatible = slots.rules.filter((rule) => deriveRule(rule, slots.known) === trueValue.active);
const needed = slots.rules.filter((rule) => deriveRule(rule, slots.known) === falseValue.active);
return { derived: derived, compatible: compatible, needed: needed };

