const needed = $derive.needed.map((value) => value.name).join(", ");
const compatible = $derive.compatible.map((value) => value.name).join(", ");
let main;
if ($derive.needed.length === 0 && $derive.compatible.length === 0) {
  main = names + " follow necessarily from the given rules.";
} else if ($derive.needed.length === 1 && $derive.compatible.length === 1) {
  main = names + " follows necessarily, and " + compatible[0] + " is not compatible with the given rules.";
} else if ($derive.needed.length === 1) {
  main = names + " follows necessarily, but " + $derive.needed[0] + " is not compatible with " + compatible[0] + ".";
} else {
  main = names + " follow necessarily, and " + compatible[0] + " is compatible with " + $derive.needed[0] + ".";
}
return main;

